      <% if @current_question %>
        <div class="stage-question__num" id="question-progress"><%= h @progress %></div>
        <div class="stage-question__body" id="question-body"><%= h @current_question.body %></div>
        <% if @game.open? %>
          <ol class="stage-options" id="options-list">
            <% @options.each_with_index do |opt, idx| %>
              <% letter = ("A".ord + idx).chr %>
              <li class="stage-option" data-option-id="<%= opt.id %>">
                <span class="stage-option__letter"><%= letter %></span>
                <span class="stage-option__title"><%= h opt.text %></span>
              </li>
            <% end %>
          </ol>
        <% else %>
          <ol class="stage-options stage-options--results" id="options-list">
            <% total_answers = @answers_count.nonzero? || 1 %>
            <% @options.each_with_index do |opt, idx| %>
              <% letter = ("A".ord + idx).chr %>
              <% cnt = @counts[opt.id] || 0 %>
              <% share = (cnt.to_f / total_answers * 100).round %>
              <li class="stage-option <%= "is-correct" if opt.correct? %>" data-option-id="<%= opt.id %>">
                <span class="stage-option__bar" style="--share: <%= share %>%"></span>
                <span class="stage-option__letter"><%= letter %></span>
                <span class="stage-option__title"><%= h opt.text %></span>
                <span class="stage-option__count" id="count-<%= opt.id %>"><%= cnt %></span>
                <% if opt.correct? %>
                  <span class="play-option__mark">Correct</span>
                <% end %>
              </li>
            <% end %>
          </ol>
        <% end %>
        <div style="margin-top: 24px; display: flex; gap: 16px; align-items: center; flex-wrap: wrap;">
          <span class="counter-pill" id="players-counter" style="margin-top:0">Players: <%= @players_count %></span>
          <span class="answers-counter" id="answers-counter">Answers: <%= @answers_count %> / <%= @players_count %></span>
        </div>
      <% else %>
        <div class="stage-question__body">No question available</div>
        <div class="counter-pill" id="players-counter">Players: <%= @players_count %></div>
      <% end %>
    <% elsif @game.ended? %>
      <div class="stage-question__body" id="over-message">The quiz is over</div>
